#include <algorithm>
struct JumpConfig {
    int bufferTicks = 5;
    int graceTicks = 4;
};
struct JumpAssist {
    int buffer = 0;
    int grace = 0;
};

bool TryStartJump(JumpAssist& s, bool jumpPressed,
                  bool isGrounded, const JumpConfig& cfg) {
    // 60Hz FixedUpdate에서 틱당 1회 호출.
    if (jumpPressed) s.buffer = cfg.bufferTicks;
    if (isGrounded) s.grace = cfg.graceTicks;
    const bool trigger = s.buffer > 0 && s.grace > 0;
    if (trigger) {
        s.buffer = 0;
        s.grace = 0;   // 같은 착지에서 재발동 방지
    } else {
        s.buffer = std::max(0, s.buffer - 1);
        s.grace = std::max(0, s.grace - 1);
    }
    return trigger;
}
// true 반환 시 CharacterMotor에서 상향 속도 부여.
// 실제 구현에서는 입력 타임스탬프와 접촉 갱신 순서를
// 함께 고려해 만료 프레임을 단위 테스트할 것.

enum class Mouth { Empty, Inhaling, Loaded };
struct MouthState {
    Mouth mode = Mouth::Empty;
    int enemyId = -1;
};
struct Candidate {
    int id = -1;
    bool capturable = false;
    bool inFront = false;
    float distance = 0.0f;
};
struct MouthEvent {
    int capturedId = -1;
    int firedId = -1;
};
MouthEvent TickMouth(MouthState& s,
                     bool inhaleHeld, bool firePressed,
                     const Candidate& t, float range) {
    MouthEvent e;
    if (s.mode == Mouth::Loaded) {
        if (firePressed) {
            e.firedId = s.enemyId;
            s.enemyId = -1;
            s.mode = Mouth::Empty;
        }
        return e;
    }
    if (!inhaleHeld) { s.mode = Mouth::Empty; return e; }
    s.mode = Mouth::Inhaling;
    if (t.id >= 0 && t.capturable &&
        t.inFront && t.distance <= range) {
        e.capturedId = t.id;
        s.enemyId = t.id;
        s.mode = Mouth::Loaded;
    }
    return e;
}
// capturedId: 월드가 적을 포획/제거하고 소유권 이전.
// firedId: 월드가 단 한 번 발사체 생성.
// 이 예시는 실제 원작 소스가 아닌 개념용 상태 머신.
